	r := &netbirdRollout{cell: "gru", conn: conn, fence: &releaseFence{kv: kv, fencer: &fenceLease{}}, services: &specRegistry{}, artifacts: netbirdArtifactStore(t, conn)}
	if deniedDigest != "" {
		r.conn = connect("admission")
	}
	return r, pin, js
}

func netbirdStageELF(payload string) []byte {
	wire := make([]byte, 64)
	copy(wire, "\x7fELF\x02\x01\x01")
	binary.LittleEndian.PutUint16(wire[16:], 2)
	binary.LittleEndian.PutUint16(wire[18:], 62)
	binary.LittleEndian.PutUint32(wire[20:], 1)
	binary.LittleEndian.PutUint16(wire[52:], 64)
	return append(wire, payload...)
}

func netbirdStageDigest(body []byte) string {
	digest := sha256.Sum256(body)
	return hex.EncodeToString(digest[:])
}

func netbirdStageTestPin(t *testing.T, body []byte) client.Pin {
	t.Helper()
	pin, err := client.LoadPin("../../deploy/image/image-inputs.json")
	if err != nil {
		t.Fatal(err)
	}
	pin.Archives.AMD64.BinarySHA256 = netbirdStageDigest(body)
	return pin
}

func LoadPin(path string) (Pin, error) {
	var inputs map[string]jsontext.Value
	b, err := os.ReadFile(path)
	if err != nil {
		return Pin{}, err
	}
	if err = json.Unmarshal(b, &inputs); err != nil {
		return Pin{}, err
	}
	raw, ok := inputs["netbird"]
	if !ok {
		return Pin{}, errors.New("missing NetBird input pin")
	}
	return ValidatePinJSON(raw)
}

