func newNetBirdBootstrapFixture(t *testing.T) netbirdBootstrapFixture {
	t.Helper()
	dir := t.TempDir()
	f := netbirdBootstrapFixture{configPath: filepath.Join(dir, "netbird.json"),
		config: netbird.Config{ManagementURL: netbird.DefaultManagementURL, Region: "sa-saopaulo-1",
			SetupKeySecretID: "ocid1.vaultsecret.oc1.sa-saopaulo-1.bootstrap"}}
	for name, value := range map[string]any{"netbird.json": f.config, "netbird-pin.json": netbirdArtifactTestPin(t)} {
		wire, err := json.Marshal(value)
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(dir, name), wire, 0644); err != nil {
			t.Fatal(err)
		}
	}
	f.runner = netbirdBootstrapRuntime{binary: filepath.Join(dir, "netbird"), fallback: filepath.Join(dir, "fallback"),
		status: func(context.Context) (client.ManagedResult, error) { return client.ManagedResult{}, nil },
		defaults: func(_ context.Context, path string, requirePin bool) (client.Pin, netbird.Config, error) {
			cfg, err := netbird.LoadConfig(path)
			if err != nil || !requirePin {
				return client.Pin{}, cfg, err
			}
			body, err := os.ReadFile(filepath.Join(filepath.Dir(path), "netbird-pin.json"))
			if err != nil {
				return client.Pin{}, cfg, err
			}
			var pin client.Pin
			if err := json.Unmarshal(body, &pin, json.RejectUnknownMembers(true)); err != nil {
				return client.Pin{}, cfg, err
			}
			return pin, cfg, client.ValidatePin(pin)
		},
		install: func(context.Context, client.Pin, netbird.Config, client.ManagedOptions) (client.ManagedResult, error) {
			t.Fatal("unexpected bootstrap installation")
			return client.ManagedResult{}, nil
		},
		confirm: func(context.Context, string) error { t.Fatal("unexpected bootstrap confirmation"); return nil },
		enroll:  func(context.Context, netbird.Config) error { t.Fatal("unexpected bootstrap enrollment"); return nil },
	}
	if err := os.WriteFile(f.runner.fallback, netbirdArtifactELF(runtime.GOARCH), 0600); err != nil {
		t.Fatal(err)
	}
	return f
}

func runNetBirdEnroll(ctx context.Context, args []string, output io.Writer) error {
	flags := flag.NewFlagSet("netbird-enroll", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	configPath := flags.String("config", "", "public NetBird enrollment configuration")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if flags.NArg() != 0 {
		return errors.New("netbird-enroll accepts no positional arguments")
	}
	if os.Geteuid() != 0 {
		return errors.New("netbird-enroll must run as root")
	}
	return enrollNetBirdBootstrap(ctx, *configPath, output, netbirdBootstrapRuntime{
		binary: "/usr/local/bin/netbird", fallback: "/usr/local/lib/terrascale-orchestrator/netbird-client",
		status: client.ManagedStatus, defaults: client.ReadBootstrapConfig, install: client.InstallManaged, confirm: client.ConfirmManaged,
		enroll: func(ctx context.Context, _ netbird.Config) error { return client.EnrollBootstrap(ctx, *configPath) },
	})
}

type netbirdBootstrapRuntime struct {
	binary, fallback string
	status           func(context.Context) (client.ManagedResult, error)
	defaults         func(context.Context, string, bool) (client.Pin, netbird.Config, error)
	install          func(context.Context, client.Pin, netbird.Config, client.ManagedOptions) (client.ManagedResult, error)
	confirm          func(context.Context, string) error
	enroll           func(context.Context, netbird.Config) error
}

func enrollNetBirdBootstrap(ctx context.Context, configPath string, output io.Writer, runner netbirdBootstrapRuntime) error {
	// Recovery may restore the public config; read it only after the journal.
	transaction, err := runner.status(ctx)
	if err != nil {
		return err
	}
	bootstrapPending := transaction.Pending && transaction.Bootstrap
	if transaction.Pending && !bootstrapPending {
		return errors.New("NetBird enrollment waits for the controller-owned managed transaction")
	}
	_, binaryErr := os.Lstat(runner.binary)
	if binaryErr != nil && !errors.Is(binaryErr, os.ErrNotExist) {
		return binaryErr
	}
	if errors.Is(binaryErr, os.ErrNotExist) && transaction.TransactionID != "" && !transaction.Bootstrap {
		return errors.New("missing NetBird client awaits the controller-owned fenced rollout")
	}
	needsPin := errors.Is(binaryErr, os.ErrNotExist) || bootstrapPending
	pin, cfg, err := runner.defaults(ctx, configPath, needsPin)
	if err != nil {
		return err
	}
	if needsPin {
		archive, err := pin.Archive(runtime.GOARCH)
		if err != nil {
			return err
		}
		if err := client.VerifyBinary(runner.fallback, archive.BinarySHA256, runtime.GOARCH); err != nil {
			if bootstrapPending {
				return fmt.Errorf("NetBird bootstrap transaction awaits its verified fallback: %w", err)
			}
			fmt.Fprintln(output, "NetBird install held for authenticated cell artifact delivery")
			return nil
		}
		transactionID := transaction.TransactionID
		if !bootstrapPending {
			transactionID = entityid.New()
		}
		installed, err := runner.install(ctx, pin, cfg, client.ManagedOptions{BinaryPath: runner.fallback, TransactionID: transactionID, Bootstrap: true})
		if err != nil {
			return err
		}
		if err := runner.confirm(ctx, installed.TransactionID); err != nil {
			return err
		}
	}
	if err := runner.enroll(ctx, cfg); err != nil {
		return err
	}
	fmt.Fprintln(output, "NetBird connected to TerraScale management and signal")
	return nil
}

func LoadConfig(path string) (Config, error) {
	return loadConfig(path, false)
}

func loadConfig(path string, rootOwned bool) (Config, error) {
	if path == "" || !strings.HasPrefix(path, "/") {
		return Config{}, errors.New("netbird-enroll requires an absolute --config path")
	}
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return Config{}, errors.New("cannot open NetBird enrollment configuration")
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !(ownedRegular(info, 0o022) || rootOwned && rootOwnedRegular(info, 0o022)) || info.Size() > maxConfigBytes {
		owner := "root"
		if rootOwned {
			owner = "root or the caller"
		}
		return Config{}, fmt.Errorf("NetBird configuration must be a regular file owned by %s, without group or other write access, and at most %d bytes", owner, maxConfigBytes)
	}
	wire, err := io.ReadAll(io.LimitReader(file, maxConfigBytes+1))
	if err != nil || len(wire) > maxConfigBytes {
		return Config{}, errors.New("cannot read bounded NetBird enrollment configuration")
	}
	var cfg Config
	if err := json.Unmarshal(wire, &cfg, json.RejectUnknownMembers(true)); err != nil {
		return Config{}, errors.New("invalid NetBird enrollment configuration JSON")
	}
	return cfg.normalized()
}

func (cfg Config) normalized() (Config, error) {
	if cfg.ManagementURL == "" {
		cfg.ManagementURL = DefaultManagementURL
	}
	if cfg.Region == "" {
		cfg.Region = DefaultRegion
	}
	manager, err := normalizeManagerURL(cfg.ManagementURL)
	if err != nil {
		return Config{}, err
	}
	cfg.ManagementURL = manager
	if cfg.ManagementIP != "" {
		ip, err := netip.ParseAddr(cfg.ManagementIP)
		if err != nil || !ip.IsPrivate() || ip.Zone() != "" || ip.Is4In6() {
			return Config{}, errors.New("NetBird management_ip must be a private IPv4 or IPv6 address")
		}
		cfg.ManagementIP = ip.String()
	}
	if !ValidSecretID(cfg.Region, cfg.SetupKeySecretID) {
		return Config{}, errors.New("NetBird setup_key_secret_id must identify an OCI Vault secret in the configured region")
	}
	if cfg.AdminPATSecretID != "" && !ValidSecretID(cfg.Region, cfg.AdminPATSecretID) {
		return Config{}, errors.New("NetBird admin_pat_secret_id must identify an OCI Vault secret in the configured region")
	}
	if err := ValidatePeerNames(cfg.PeerNames); err != nil {
		return Config{}, err
	}
	return cfg, nil
}

func normalizeManagerURL(value string) (string, error) {
	parsed, err := url.Parse(value)
	if err != nil || parsed.Scheme != "https" || parsed.User != nil || parsed.Opaque != "" ||
		parsed.Host != managerHostname && parsed.Host != managerHostname+":443" || strings.Contains(value, "#") ||
		parsed.Path != "" && parsed.Path != "/" || parsed.RawPath != "" || parsed.RawQuery != "" || parsed.ForceQuery || parsed.Fragment != "" || parsed.RawFragment != "" {
		return "", errors.New("NetBird management_url must be https://netbird.terrascale.tech")
	}
	return DefaultManagementURL, nil

func VerifyBinary(path, expected, architecture string) error {
	return verifyBinaryLimit(path, expected, architecture, MaxBinaryBytes)
}

func verifyBinaryLimit(path, expected, architecture string, maximum int64) error {
	if !SHA256Pattern.MatchString(expected) {
		return errors.New("NetBird binary SHA-256 must be 64 lowercase hex characters")
	}
	f, e := openBoundedFileLimit(path, 64, maximum)
	if e != nil {
		return e
	}
	defer f.Close()
	var header [64]byte
	if _, e = io.ReadFull(f, header[:]); e != nil {
		return e
	}
	machine := uint16(183)
	if architecture == "amd64" {
		machine = 62
	} else if architecture != "arm64" {
		return errors.New("unsupported architecture")
	}
	if string(header[:7]) != "\x7fELF\x02\x01\x01" || (binary.LittleEndian.Uint16(header[16:]) != 2 && binary.LittleEndian.Uint16(header[16:]) != 3) || binary.LittleEndian.Uint16(header[18:]) != machine || binary.LittleEndian.Uint32(header[20:]) != 1 || binary.LittleEndian.Uint16(header[52:]) != 64 {
		return fmt.Errorf("NetBird binary must be an ELF64 little-endian %s executable", architecture)
	}
	h := sha256.New()
	h.Write(header[:])
	n, e := io.Copy(h, io.LimitReader(f, maximum+1-int64(len(header))))
	if e != nil {
		return e
	}
	if n+int64(len(header)) > maximum {
		return fmt.Errorf("NetBird binary exceeds %d bytes", maximum)
	}
	if hex.EncodeToString(h.Sum(nil)) != expected {
		return errors.New("NetBird binary bytes differ from the pinned SHA-256")
	}
	return nil
}

func openBoundedFileLimit(path string, minimum, maximum int64) (*os.File, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() < minimum || info.Size() > maximum {
		file.Close()
		return nil, fmt.Errorf("NetBird source must be a direct regular file within %d bytes", maximum)
	}
	return file, nil
}

