func fenceKV(t *testing.T) jetstream.KeyValue {
	t.Helper()
	kv, _, _ := fenceBroker(t)
	return kv
}

func fenceBroker(t *testing.T) (jetstream.KeyValue, *nats.Conn, jetstream.JetStream) {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	srv.Start()
	t.Cleanup(srv.Shutdown)
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	kv, err := js.CreateKeyValue(t.Context(), jetstream.KeyValueConfig{Bucket: "TS_RELEASE_CHANNEL"})
	if err != nil {
		t.Fatal(err)
	}
	return kv, conn, js
}

func (f *releaseFence) loadJSON(ctx context.Context, key string, value any) error {
	entry, err := f.kv.Get(ctx, key)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return os.ErrNotExist
	}
	if err != nil {
		return err
	}
	return json.Unmarshal(entry.Value(), value, json.RejectUnknownMembers(true))
}

// keys lists the bucket's keys that match filter.
func (f *releaseFence) keys(ctx context.Context, filter string) ([]string, error) {
	lister, err := f.kv.ListKeysFiltered(ctx, filter)
	if errors.Is(err, jetstream.ErrNoKeysFound) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	defer lister.Stop()
	var keys []string
	for key := range lister.Keys() {
		keys = append(keys, key)
	}
	// The lister closes early, without an error, when ctx ends.
	return keys, ctx.Err()
}

func (f *releaseFence) record(ctx context.Context, node string) (fenceRecord, bool, error) {
	entry, err := f.kv.Get(ctx, fencedKey(node))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return fenceRecord{}, false, nil
	}
	if err != nil {
		return fenceRecord{}, false, err
	}
	var record fenceRecord
	if err := json.Unmarshal(entry.Value(), &record); err != nil {
		return fenceRecord{}, false, fmt.Errorf("decode the fence of %s: %w", node, err)
	}
	return record, true, nil
}

func (f *releaseFence) save(ctx context.Context, epoch uint64, node string, record fenceRecord) error {
	wire, err := json.Marshal(record)
	if err != nil {
		return err
	}
	if err := f.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = f.kv.Put(ctx, fencedKey(node), wire)
	return err
}

// restore lets holder go of node's fence. When no other holder keeps the
// node out, it returns the recorded backends to rotation on the load
// balancer they were taken from and, with healthy, waits until their
// health checks pass; it reports whether any were returned.
func (f *releaseFence) restore(ctx context.Context, api lb.API, epoch uint64, node, holder string, healthy bool) (bool, error) {
	unlock, err := f.lockNodeContext(ctx, node)
	if err != nil {
		return false, err
	}
	defer unlock()
	return f.restoreLocked(ctx, api, epoch, node, holder, healthy)
}

// restoreLocked is restore with node's lock held.
func (f *releaseFence) restoreLocked(ctx context.Context, api lb.API, epoch uint64, node, holder string, healthy bool,
) (bool, error) {
	record, found, err := f.record(ctx, node)
	if err != nil || !found {
		return false, err
	}
	if others := slices.DeleteFunc(slices.Clone(record.holders()), func(h string) bool { return h == holder }); len(others) > 0 {
		if len(others) == len(record.holders()) {
			return false, nil
		}
		record.Holders = others
		return false, f.save(ctx, epoch, node, record)
	}
	// Recorded as back in rotation before the load balancer changes, so a
	// restore cut short leaves a record the next fence drains again; the
	// holder stays on it until it is gone, so the holder finishes it.
	record.Holders = []string{holder}
	for i := range record.Backends {
		record.Backends[i].Offline = false
	}
	if err := f.save(ctx, epoch, node, record); err != nil {
		return false, err
	}
	for _, backend := range record.Backends {
		if err := f.update(ctx, api, epoch, backend, false, false); err != nil {
			return false, err
		}
	}
	for _, backend := range record.Backends {
		name := lb.Backend{IP: backend.IP, Port: backend.Port}.Name()
		for healthy {
			unhealthy, err := api.UnhealthyBackends(ctx, backend.LoadBalancerID, backend.Set)
			if err != nil {
				return false, err
			}
			if !unhealthy[name] {
				break
			}
			if err := f.wait(ctx, epoch, fencePoll); err != nil {
				return false, fmt.Errorf("%s backend %s did not pass its health check: %w", backend.Set, name, err)
			}
		}
	}
	if err := f.fencer.Guard(ctx, epoch); err != nil {
		return false, err
	}
	slog.InfoContext(ctx, "release fence returned a node to rotation", observability.ComponentKey, "rollout", "node", node)
	return len(record.Backends) > 0, f.kv.Delete(ctx, fencedKey(node))
}

preflight.text:
func (n *netbirdRollout) status(ctx context.Context, node string) (network.Status, error) {
	var status network.Status
	if err := n.load(ctx, "netbird.status."+node, &status); err != nil {
		return status, fmt.Errorf("NetBird worker on %s has not reported: %w", node, err)
	}
	if time.Since(status.ObservedAt) > 15*time.Second {
		return status, fmt.Errorf("NetBird worker on %s is stale", node)
	}
	return status, nil
}

func (n *netbirdRollout) preflight(ctx context.Context, node string) error {
	if err := n.artifactsReady(ctx); err != nil {
		return err
	}
	spec, addresses, err := n.preflightAddresses(ctx, node)
	if err != nil {
		return err
	}
	if spec == nil || addresses[node] == "" || len(addresses) < 2 {
		return errors.New("NetBird upgrade requires a release fence and at least two granted nodes")
	}
	leader := n.services.controllerNode(n.cell, n.cfg.NATS.Instance)
	probe, err := n.status(ctx, leader)
	if err != nil {
		return err
	}
	if probe.Missing || probe.Version == "" || !probe.Connected {
		return errors.New("NetBird probing leader has no working mesh client; restore verified bootstrap enrollment over OCI before draining")
	}
	// Refuse a cell already being drained by another rollout. Quorum guards
	// in fence.fence still serialize every actual LB removal.
	keys, err := n.fence.keys(ctx, fencedKey("*"))
	if err != nil {
		return err
	}
	for _, key := range keys {
		record, found, err := n.fence.record(ctx, strings.TrimPrefix(key, fencedKey("")))
		if err != nil {
			return err
		}
		if found && slices.ContainsFunc(record.holders(), func(holder string) bool { return holder != netbirdHold }) {
			return fmt.Errorf("NetBird rollout waits for existing fence on %s", strings.TrimPrefix(key, fencedKey("")))
		}
	}
	if n.nodes != nil && n.nodes.cluster != nil {
		if err := n.nodes.cluster(ctx, node); err != nil {
			return err
		}
	}
	// Verify ordinary SSH on the OCI VCN address. We never change sshd,
	// networking, security lists, public IPs or this independent path.
	if err := n.recoverySSH(ctx, node, addresses[node]); err != nil {
		return fmt.Errorf("OCI SSH recovery path for %s is unavailable: %w", node, err)
	}
	selected, err := n.status(ctx, node)
	if err != nil {
		return err
	}
	bootstrapRemote := selected.Missing && selected.Version == "" && node != n.services.controllerNode(n.cell, n.cfg.NATS.Instance)
	for candidate := range addresses {
		status, err := n.status(ctx, candidate)
		if err != nil {
			return err
		}
		if status.Pending != "" || status.Error != "" {
			return fmt.Errorf("NetBird preflight %s has an unresolved worker operation", candidate)
		}
		// Several joining nodes may need their first authenticated install.
		// Only explicit executable absence can skip mesh health; a failed
		// observation of an installed daemon must still hold the rollout.
		if status.Missing && status.Version == "" {
			continue
		}
		// An unchanged installed leader can admit its first missing peer.
		// Confirmation still proves that peer's traffic over the mesh.
		if err := n.healthyMesh(ctx, candidate, status, time.Time{}, !bootstrapRemote); err != nil {
			return fmt.Errorf("NetBird preflight %s: %w", candidate, err)
		}
	}
	return nil
}

func netbirdAdmittedFence(record network.Record) (*cellspec.ReleaseFence, error) {
	var admitted *cellspec.ReleaseFence
	if err := json.Unmarshal(record.Fence, &admitted, json.RejectUnknownMembers(true)); err != nil {
		return nil, fmt.Errorf("decode admitted NetBird fence: %w", err)
	}
	if admitted == nil {
		return nil, errors.New("NetBird admission has no release fence")
	}
	if err := netbirdOCIAddress(record.OCIAddress); err != nil {
		return nil, err
	}
	return admitted, nil
}

func (n *netbirdRollout) preflightAddresses(ctx context.Context, node string) (*cellspec.ReleaseFence, map[string]string, error) {
	spec, addresses := n.addresses()
	state, err := n.state(ctx)
	if err != nil {
		return nil, nil, err
	}
	record := state.Record
	if record.ID != "" && record.Node == node && record.Phase != "done" && !record.RecoveryComplete && len(record.Fence) > 0 {
		spec, err = netbirdAdmittedFence(record)
		if err != nil {
			return nil, nil, err
		}
		// Only the admitted node keeps its saved address. Peers still come
		// from the current inventory and pass live health/quorum checks.
		addresses[node] = record.OCIAddress
	}
	return spec, addresses, nil
}

func (n *netbirdRollout) healthy(ctx context.Context, node string, status network.Status, since time.Time) error {
	return n.healthyMesh(ctx, node, status, since, true)
}

func (n *netbirdRollout) healthyMesh(ctx context.Context, node string, status network.Status, since time.Time, verifyLeaderPeer bool) error {
	address, err := netip.ParseAddr(status.IP)
	if !status.Connected || err != nil || !netbirdClientRange.Contains(address) || !strings.HasSuffix(status.DNS, ".nb.ts.internal") || len(status.DNS) > 255 {
		return errors.New("NetBird management, signal, mesh IP and peer DNS name are not ready")
	}
	ctx, cancel := context.WithTimeout(ctx, 8*time.Second)
	defer cancel()
	// The leader's own mesh address is locally routed. Prove a remote peer
	// too, so an isolated leader cannot confirm itself using loopback traffic.
	if verifyLeaderPeer && node == n.services.controllerNode(n.cell, n.cfg.NATS.Instance) {
		_, addresses := n.addresses()
		peers := make([]string, 0, len(addresses))
		for peer := range addresses {
			if peer != node && n.nodes != nil && n.nodes.controllers != nil && n.nodes.controllers(peer) {
				peers = append(peers, peer)
			}
		}
		slices.Sort(peers)
		if len(peers) == 0 {
			return errors.New("NetBird leader has no remote controller peer to verify")
		}
		if err := n.healthyRemotePeer(ctx, peers); err != nil {
			return err
		}
	}

func (n *netbirdRollout) healthyRemotePeer(ctx context.Context, peers []string) error {
	last := errors.New("no installed healthy remote controller")
	for _, node := range peers {
		status, err := n.status(ctx, node)
		if err != nil {
			last = err
			continue
		}
		if status.Missing || status.Pending != "" || status.Error != "" {
			continue
		}
		// One unreachable peer must not consume the entire leader deadline.
		attempt, cancel := context.WithTimeout(ctx, 3*time.Second)
		err = n.healthy(attempt, node, status, time.Time{})
		cancel()
		if err == nil {
			return nil
		}
		last = fmt.Errorf("%s: %w", node, err)
	}
	return fmt.Errorf("NetBird leader cannot reach a healthy controller peer: %w", last)
}

reconciler.text:
func (r *Reconciler) Tick(ctx context.Context, target Target, nodes []string) error {
	currentTime := func() time.Time {
		if r.Now != nil {
			return r.Now().UTC()
		}
		return time.Now().UTC()
	}
	now := currentTime()
	record, err := r.Load(ctx)
	if err != nil {
		return err
	}
	if record.Phase != "" && !entityid.Valid(record.ID) {
		return errors.New("invalid NetBird rollout identity")
	}
	if record.RecoveryReturning && !record.RecoveryComplete {
		// Fence an interrupted return before any status or health gate.
		if err := r.Drain(ctx, record.Node); err != nil {
			return err
		}
		record.RecoveryReturning = false
		if err := r.Save(ctx, record); err != nil {
			return err
		}
	}
	returnNode := func() error {
		record.RecoveryReturning = true
		if err := r.Save(ctx, record); err != nil {
			return err
		}
		if err := r.Return(ctx, record.Node); err != nil {
			// Return may clear backend flags before its health check fails.
			if drainErr := r.Drain(ctx, record.Node); drainErr != nil {
				return errors.Join(err, drainErr)
			}
			record.RecoveryReturning = false
			return errors.Join(err, r.Save(ctx, record))
		}
		record.RecoveryReturning = false
		return nil
	}
	rollbackAcknowledged := func(status Status) bool {
		return status.ActionID == CommandID(record.ID, "rollback") && status.Error == "" && status.Version == record.Previous && status.Pending == ""
	}
	recovered := func(status Status, since time.Time) error {
		if record.Previous == "" {
			// First-install rollback restores absence, so mesh probes cannot run.
			if !status.Missing || status.Version != "" || status.ObservedAt.IsZero() ||
				now.Sub(status.ObservedAt) > 15*time.Second || status.ObservedAt.Sub(now) > 2*time.Second {
				return errors.New("previous NetBird absence has not been freshly observed")
			}
			return nil
		}
		return r.Healthy(ctx, record.Node, status, since)
	}
	hash := Hash(target)
	if record.Phase == "failed" {
		// Recover the held node even when this pin stays failed or is removed.
		// The completion marker is written only after our fence is released.
		if !record.RecoveryComplete {
			status, err := r.Status(ctx, record.Node)
			// Older journals lack the marker. Require proof of recovery unless
			// this controller explicitly recorded that no agent mutation began.
			if err != nil || status.Pending != "" || status.Error != "" || (record.RollbackRequired == nil || *record.RollbackRequired) && !rollbackAcknowledged(status) {
				return errors.New("previous NetBird rollback is unresolved")
			}
			if err := recovered(status, time.Time{}); err != nil {
				return err
			}
			if err := returnNode(); err != nil {
				return err
			}
			record.RecoveryComplete = true
			if err := r.Save(ctx, record); err != nil {
				return err
			}
		}
		if record.PinHash == hash {
			return fmt.Errorf("NetBird rollout held on %s: %s", record.Node, record.Reason)
		}
	}
	if record.Phase == "" || record.Phase == "done" || record.Phase == "failed" {
		statuses := make(map[string]Status, len(nodes))
		for _, node := range nodes {
			status, err := r.Status(ctx, node)
			if err != nil {
				return err
			}
			if status.Pending != "" || status.Error != "" {
				return fmt.Errorf("NetBird transaction still pending on %s", node)
			}
			statuses[node] = status
		}
		for _, node := range nodes {
			status := statuses[node]
			if status.Version != "" {
				comparison, err := CompareVersions(status.Version, target.Pin.Version)
				if err != nil {
					return err
				}
				if comparison == 0 && status.AppliedTargetHash == hash {
					continue
				}
			}
			if err := r.Preflight(ctx, node); err != nil {
				return err
			}
			record = Record{ID: entityid.New(), Node: node, Previous: status.Version,
				Target: target, PinHash: hash, Phase: "drain", StartedAt: now, Deadline: now.Add(10 * time.Minute)}
			return r.Save(ctx, record)
		}
		return nil
	}
	transition := func(phase string) error { record.Phase = phase; return r.Save(ctx, record) }
	command := func(action string) error {
		return r.Send(ctx, record.Node, Command{ID: CommandID(record.ID, action), Generation: uint64(record.StartedAt.UnixNano()), Transaction: record.ID, Action: action, Target: record.Target})
	}
	rollback := func(reason string) error {
		record.RollbackRequired = new(true)
		record.Reason = reason
		record.Deadline = now.Add(6 * time.Minute)
		return transition("rollback")
	}
	switch record.Phase {
	case "drain":
		if now.After(record.Deadline) {
			record.RollbackRequired = new(false)
			record.Reason = "drain timed out"
			return transition("failed")
		}
		if err := r.Preflight(ctx, record.Node); err != nil {
			return err
		}
		if err := r.Drain(ctx, record.Node); err != nil {
			return err
		}
		record.Deadline = currentTime().Add(3 * time.Minute)
		return transition("install")
	case "install":
		if now.After(record.Deadline) {
			return rollback("agent did not acknowledge installation")
		}
		status, err := r.Status(ctx, record.Node)
		if err != nil {
			return err
		}
		if status.ActionID == CommandID(record.ID, "install") {
			if status.Error != "" {
				return rollback(status.Error)
			}
			record.Deadline = now.Add(2 * time.Minute)
			return transition("check")
		}
		return command("install")
	case "check":
		status, err := r.Status(ctx, record.Node)
		if err == nil && status.Version == record.Target.Pin.Version && status.Pending == record.ID {
			err = r.Healthy(ctx, record.Node, status, record.StartedAt)
			if err == nil {
				record.Deadline = currentTime().Add(2 * time.Minute)
				return transition("confirm")
			}
		}
		if now.After(record.Deadline) {
			return rollback("new NetBird agent failed mesh health checks")
		}
		return err
	case "confirm":
		if now.After(record.Deadline) {
			return rollback("new NetBird agent was not confirmed")
		}
		status, err := r.Status(ctx, record.Node)
		if err != nil {
			return err
		}
		if status.ActionID == CommandID(record.ID, "confirm") && status.Error == "" && status.Pending == "" && status.Version == record.Target.Pin.Version && status.AppliedTargetHash == record.PinHash {
			record.Deadline = now.Add(2 * time.Minute)
			return transition("return")
		}
		return command("confirm")
	case "return":
		failedReturn := func(err error) error {
			if now.After(record.Deadline) {
				return rollback("confirmed NetBird agent failed return health checks")
			}
			return err
		}
		status, err := r.Status(ctx, record.Node)
		if err != nil {
			return failedReturn(err)
		}
		if status.Pending != "" || status.Version != record.Target.Pin.Version || status.AppliedTargetHash != record.PinHash || status.ActionID != CommandID(record.ID, "confirm") || status.Error != "" {
			return failedReturn(errors.New("confirmed NetBird transaction changed before return"))
		}
		if err := r.Healthy(ctx, record.Node, status, record.StartedAt); err != nil {
			return failedReturn(err)
		}
		if err := returnNode(); err != nil {
			return failedReturn(err)
		}
		return transition("done")
	case "rollback":
		// Return may have put backends online before an LB health check
		// failed. Re-establish the same fence before restarting the old agent.
		if err := r.Drain(ctx, record.Node); err != nil {
			return err
		}
		if err := command("rollback"); err != nil {
			return err
		}
		// Safe re-draining can wait for repaired quorum across many ticks.
		// Allow a full acknowledgment window once the command is sent.
		record.Deadline = currentTime().Add(6 * time.Minute)
		return transition("rollback-check")
	case "rollback-check":
		status, err := r.Status(ctx, record.Node)
		if err == nil && rollbackAcknowledged(status) && recovered(status, record.StartedAt) == nil {
			if err := returnNode(); err != nil {
				if record.RecoveryReturning {
					return err
				}
				if now.After(record.Deadline) {
					record.Reason += "; previous binary failed return health checks (node remains drained)"
					return transition("failed")
				}
				return err
			}
			record.RecoveryComplete = true
			return transition("failed")
		}
		if now.After(record.Deadline) {
			if err := r.Drain(ctx, record.Node); err != nil {
				return err
			}
			record.Reason += "; previous binary did not recover (node remains drained)"
			return transition("failed")
		}
		return command("rollback")
	default:
		return errors.New("unknown NetBird rollout phase")
	}
}
